62	type CtaLink = { label: string; href: string };
63	
64	/**
65	 * The site-wide closing CTA band. Parameterized so bespoke pages reuse the exact
66	 * same glass/aura treatment instead of forking their own copy of it — pass
67	 * `title`/`sub`/`primary`/`secondary`/`note` to override, or render `<CtaBand />`
68	 * for the default deploy-your-server promise. Defaults keep every existing
69	 * caller (business-email, nxcloud, …) byte-for-byte unchanged.
70	 */
71	export function CtaBand({
72	  title,
73	  sub,
74	  primary,
75	  secondary,
76	  note,
77	}: {
78	  title?: React.ReactNode;
79	  sub?: React.ReactNode;
80	  primary?: CtaLink;
81	  secondary?: CtaLink;
82	  note?: React.ReactNode;
83	} = {}) {
84	  // The default band renders on many pages, so its promise is the one prospects
85	  // meet most. It once read "No credit card required to get started. Spin up a
86	  // VPS, break things, and only pay for what you keep running." — none of which
87	  // survives contact with the product: free deploys are admin-only
88	  // (`formData.get("free") === "1" && isAdmin`), a customer with no balance gets
89	  // "Insufficient balance. Top up your wallet first.", and a term is paid up
90	  // front rather than metered on what you keep running. What is true is that the
91	  // ACCOUNT is free and takes no card. Say that, and say plainly where the money
92	  // starts.
93	  const heading = title ?? (
94	    <>
95	      Deploy your first server in <span className="grad-text">under a minute</span>
96	    </>
97	  );
98	  const subCopy =
99	    sub ??
100	    "Creating an account is free and takes no card details. You pay when you deploy — choose a billing term and pay from your wallet or by card at checkout.";
101	  const primaryCta = primary ?? { label: "Create your account", href: "/register" };
102	  const secondaryCta = secondary ?? { label: "Compare plans", href: "/pricing" };
103	
104	  return (
105	    <Reveal className="relative overflow-hidden rounded-3xl border border-white/[0.08] bg-navy-850/70 px-8 py-16 text-center backdrop-blur-md sm:px-16">
106	      <div
107	        className="pointer-events-none absolute inset-0 opacity-70"
108	        style={{
109	          backgroundImage:
110	            "radial-gradient(ellipse 60% 60% at 30% 0%, rgba(59,130,246,0.18), transparent), radial-gradient(ellipse 50% 60% at 80% 100%, rgba(138,112,251,0.18), transparent)",
111	        }}
112	      />
113	      <div className="relative">
114	        <h2 className="mx-auto max-w-2xl text-3xl font-bold tracking-tight sm:text-4xl">{heading}</h2>
115	        <p className="mx-auto mt-4 max-w-xl text-lg text-slate-400">{subCopy}</p>
116	        <div className="mt-8 flex flex-wrap items-center justify-center gap-3">
117	          <Link href={primaryCta.href} className="btn-primary px-6 py-3 text-base">
118	            {primaryCta.label}
119	            <IconArrow size={16} />
120	          </Link>
121	          <Link href={secondaryCta.href} className="btn-secondary px-6 py-3 text-base">
122	            {secondaryCta.label}
123	          </Link>
124	        </div>
125	        {note && <p className="mt-5 text-sm text-slate-500">{note}</p>}
126	      </div>
127	    </Reveal>
128	  );
129	}
