3	import { useEffect, useRef } from "react";
4	
5	/**
6	 * Living Infrastructure (v5) signature: an ambient canvas node-field that drifts,
7	 * links near neighbours, and reacts to the cursor (nearby nodes lean toward it and
8	 * draw brighter links). Capped particle count + rAF for 60fps; reduced-motion or
9	 * mobile → a single static frame. Pure canvas, no assets.
10	 */
11	export function AmbientField() {
12	  const ref = useRef<HTMLCanvasElement | null>(null);
13	
14	  useEffect(() => {
15	    const canvas = ref.current;
16	    if (!canvas) return;
17	    const ctx = canvas.getContext("2d");
18	    if (!ctx) return;
19	
20	    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
21	    const dpr = Math.min(window.devicePixelRatio || 1, 2);
22	    let w = 0, h = 0;
23	    const mouse = { x: -9999, y: -9999 };
24	
25	    const COUNT = Math.min(72, Math.floor((window.innerWidth * window.innerHeight) / 26000));
26	    const pts = Array.from({ length: COUNT }, () => ({
27	      x: Math.random(), y: Math.random(),
28	      vx: (Math.random() - 0.5) * 0.00022, vy: (Math.random() - 0.5) * 0.00022,
29	    }));
30	
31	    const resize = () => {
32	      const rect = canvas.getBoundingClientRect();
33	      w = rect.width; h = rect.height;
34	      canvas.width = w * dpr; canvas.height = h * dpr;
35	      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
36	    };
37	    resize();
38	
39	    const draw = () => {
40	      ctx.clearRect(0, 0, w, h);
41	      // update + draw nodes
42	      for (const p of pts) {
43	        if (!reduce) { p.x += p.vx; p.y += p.vy; if (p.x < 0 || p.x > 1) p.vx *= -1; if (p.y < 0 || p.y > 1) p.vy *= -1; }
44	        const px = p.x * w, py = p.y * h;
45	        const dm = Math.hypot(px - mouse.x, py - mouse.y);
46	        const near = dm < 140;
47	        ctx.beginPath();
48	        ctx.arc(px, py, near ? 2.2 : 1.4, 0, Math.PI * 2);
49	        ctx.fillStyle = near ? "rgba(150,190,255,0.9)" : "rgba(120,150,220,0.5)";
50	        ctx.fill();
51	        // link to cursor
52	        if (near) {
53	          ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(mouse.x, mouse.y);
54	          ctx.strokeStyle = `rgba(99,102,241,${0.35 * (1 - dm / 140)})`; ctx.lineWidth = 0.7; ctx.stroke();
55	        }
56	      }
57	      // link near neighbours
58	      for (let i = 0; i < pts.length; i++) {
59	        for (let j = i + 1; j < pts.length; j++) {
60	          const ax = pts[i].x * w, ay = pts[i].y * h, bx = pts[j].x * w, by = pts[j].y * h;
61	          const d = Math.hypot(ax - bx, ay - by);
62	          if (d < 120) {
63	            ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(bx, by);
64	            ctx.strokeStyle = `rgba(90,110,200,${0.16 * (1 - d / 120)})`; ctx.lineWidth = 0.6; ctx.stroke();
65	          }
66	        }
67	      }
68	    };
69	
70	    let raf = 0;
71	    const loop = () => { draw(); raf = requestAnimationFrame(loop); };
72	    if (reduce) draw(); else loop();
73	
74	    const onMove = (e: MouseEvent) => { const r = canvas.getBoundingClientRect(); mouse.x = e.clientX - r.left; mouse.y = e.clientY - r.top; };
75	    const onLeave = () => { mouse.x = -9999; mouse.y = -9999; };
76	    window.addEventListener("resize", resize);
77	    window.addEventListener("mousemove", onMove);
78	    window.addEventListener("mouseout", onLeave);
79	    return () => { cancelAnimationFrame(raf); window.removeEventListener("resize", resize); window.removeEventListener("mousemove", onMove); window.removeEventListener("mouseout", onLeave); };
80	  }, []);
81	
82	  return <canvas ref={ref} className="h-full w-full" aria-hidden />;
83	}
