import fs from "node:fs";
import path from "node:path";
import Image from "next/image";
// Namespace import (never named): a computed key lookup can't produce a
// "export not found" build error, so an unknown/removed brand simply resolves
// to `undefined` at runtime and falls through to the wordmark — the component
// therefore ALWAYS renders something professional. `simple-icons` is a build
// dependency (see package.json); it resolves during `npm install` on staging.
import * as simpleIcons from "simple-icons";

/**
 * Brand mark for a competitor on the /compare surface. Resolution order, so it
 * always renders something clean on the dark theme:
 *
 *   1. `/public/logos/<slug>.svg` when an operator has dropped a real logo in.
 *   2. The Simple Icons glyph for the brand, tinted with `currentColor` (slate)
 *      so it reads on navy rather than fighting it with the brand's own hex.
 *   3. A styled wordmark pill (the competitor's name) — the graceful fallback
 *      for brands Simple Icons doesn't carry (Contabo, Cloudways, Kamatera…).
 *
 * Nxeon's own mark (`slug="nxeon"`) renders the wordmark PNG at /public/logo.png.
 * This is a server component: the fs check and icon lookup never reach the client.
 */

type SimpleIcon = { title: string; slug: string; hex: string; path: string };

// slug → Simple Icons export key. Unknown/removed keys resolve to undefined and
// fall through to the wordmark, so listing an optimistic key is always safe.
const SI_KEY: Record<string, string> = {
  digitalocean: "siDigitalocean",
  hostinger: "siHostinger",
  hetzner: "siHetzner",
  linode: "siLinode",
  ovh: "siOvh",
  vultr: "siVultr",
  aws: "siAmazonwebservices",
  godaddy: "siGodaddy",
  bluehost: "siBluehost",
  namecheap: "siNamecheap",
  hostgator: "siHostgator",
  ionos: "siIonos",
  a2hosting: "siA2hosting",
  // No Simple Icons brand mark — these intentionally use the wordmark fallback:
  //   contabo, cloudways, kamatera
};

/** Does an operator-supplied SVG exist at /public/logos/<slug>.svg? */
function hasPublicLogo(slug: string): boolean {
  try {
    return fs.existsSync(path.join(process.cwd(), "public", "logos", `${slug}.svg`));
  } catch {
    return false;
  }
}

/** Look up the Simple Icons glyph for a slug, or null if the brand isn't carried. */
function simpleIcon(slug: string): SimpleIcon | null {
  const key = SI_KEY[slug];
  if (!key) return null;
  const icon = (simpleIcons as Record<string, unknown>)[key] as SimpleIcon | undefined;
  return icon && typeof icon.path === "string" ? icon : null;
}

export function CompetitorLogo({
  slug,
  name,
  /** Target mark height in px; the wordmark scales its text to match. */
  size = 40,
  className = "",
}: {
  slug: string;
  name: string;
  size?: number;
  className?: string;
}) {
  // Nxeon's own wordmark PNG (wide lockup — contain it within the height).
  if (slug === "nxeon") {
    return (
      <Image
        src="/logo.png"
        alt="Nxeon"
        width={496}
        height={85}
        className={`w-auto object-contain ${className}`}
        style={{ height: size }}
        priority={false}
      />
    );
  }

  if (hasPublicLogo(slug)) {
    // Operator-supplied real logo. next/image with a plain <img> semantics via
    // unoptimized keeps SVGs crisp without extra domain config.
    // eslint-disable-next-line @next/next/no-img-element
    return (
      <img
        src={`/logos/${slug}.svg`}
        alt={name}
        style={{ height: size }}
        className={`w-auto object-contain ${className}`}
      />
    );
  }

  const icon = simpleIcon(slug);
  if (icon) {
    return (
      <svg
        role="img"
        aria-label={name}
        viewBox="0 0 24 24"
        style={{ height: size, width: size }}
        className={`text-slate-200 ${className}`}
      >
        <title>{name}</title>
        <path d={icon.path} fill="currentColor" />
      </svg>
    );
  }

  // Wordmark fallback — a clean, on-theme pill so the layout never looks broken.
  return (
    <span
      className={`inline-flex items-center rounded-xl border border-white/[0.10] bg-white/[0.04] px-4 font-semibold tracking-tight text-slate-100 ${className}`}
      style={{ height: size, fontSize: Math.round(size * 0.42) }}
    >
      {name}
    </span>
  );
}

import Link from "next/link";
import { Reveal } from "./Reveal";
import { IconCheck } from "./icons";
import { CompetitorLogo } from "./CompetitorLogo";

/**
 * Shared, DB-fed comparison table for the /compare surface and every
 * competitor-alternative page. One premium glass table so all comparisons read
 * as one designed thing: logo-headed columns in the order Nxeon | Feature |
 * {Competitor}, the Nxeon column emphasised with a violet tint and a highlighted
 * border, a blue/cyan check on every included Nxeon value, and an honest
 * "reflects our understanding" disclaimer baked in.
 *
 * It renders NO hard-coded Nxeon price: any Nxeon figure arrives already derived
 * from the live catalogue (see `lib/vps-price-band.ts`) via the caller, either
 * inside a row's `nxeon` string or the optional `fromLabel` header badge.
 */
export type CompareRow = { feature: string; nxeon: string; other: string };

export function CompareTable({
  competitor,
  competitorSlug,
  rows,
  fromLabel,
  note,
}: {
  /** Competitor display name, e.g. "DigitalOcean". */
  competitor: string;
  /** Brand slug for the header logo (public svg → simple-icons → wordmark). */
  competitorSlug: string;
  rows: CompareRow[];
  /** DB-fed entry price, e.g. "$6.49/mo" — shown as a header badge when given. */
  fromLabel?: string;
  /** Optional trademark / accuracy disclaimer. A sensible default is used. */
  note?: string;
}) {
  const disclaimer =
    note ??
    `${competitor} is a trademark of its respective owner. Comparison reflects Nxeon's understanding at time of writing — always check each provider's current plans.`;

  return (
    <Reveal>
      <div className="mx-auto max-w-4xl overflow-x-auto rounded-3xl border border-white/[0.08] bg-navy-900/60 p-1.5 backdrop-blur-md">
        <table className="w-full min-w-[640px] border-separate border-spacing-0 text-sm">
          <thead>
            <tr>
              {/* Nxeon — emphasised column */}
              <th className="w-[38%] rounded-t-2xl border-b border-brand-500/25 bg-gradient-to-b from-brand-500/[0.14] to-brand-500/[0.03] px-5 py-5 text-left align-middle">
                <span className="flex flex-col gap-2">
                  <CompetitorLogo slug="nxeon" name="Nxeon" size={26} />
                  {fromLabel && (
                    <span className="text-[11px] font-medium text-brand-300">
                      from <span className="font-semibold text-brand-200">{fromLabel}</span>
                    </span>
                  )}
                </span>
              </th>
              {/* Feature axis (centre) */}
              <th className="w-[24%] border-b border-white/[0.08] px-4 py-5 text-center text-[11px] font-semibold uppercase tracking-wider text-slate-500">
                Compared
              </th>
              {/* Competitor */}
              <th className="w-[38%] border-b border-white/[0.08] px-5 py-5 text-left align-middle">
                <span className="flex items-center">
                  <CompetitorLogo slug={competitorSlug} name={competitor} size={26} />
                </span>
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((r, i) => {
              const last = i === rows.length - 1;
              return (
                <tr key={r.feature} className="group">
                  {/* Nxeon value — tinted, checked */}
                  <td
                    className={`bg-brand-500/[0.05] px-5 py-4 align-top text-slate-100 ${
                      last ? "rounded-b-2xl" : "border-b border-white/[0.05]"
                    }`}
                  >
                    <span className="flex items-start gap-2.5">
                      <span className="mt-0.5 flex h-4.5 w-4.5 flex-none items-center justify-center rounded-full bg-gradient-to-br from-accent-cyan/25 to-brand-500/25 text-accent-cyan">
                        <IconCheck size={12} />
                      </span>
                      <span className="leading-snug">{r.nxeon}</span>
                    </span>
                  </td>
                  {/* Feature label */}
                  <td
                    className={`px-4 py-4 text-center align-middle text-[13px] font-medium text-slate-300 ${
                      last ? "" : "border-b border-white/[0.05]"
                    }`}
                  >
                    {r.feature}
                  </td>
                  {/* Competitor value */}
                  <td
                    className={`px-5 py-4 align-top text-slate-400 ${
                      last ? "" : "border-b border-white/[0.05]"
                    }`}
                  >
                    <span className="leading-snug">{r.other}</span>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      <p className="mt-4 text-center text-xs text-slate-500">{disclaimer}</p>
    </Reveal>
  );
}

